(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ta"] = {"ui":{"skip":"உள்ளடக்கத்துக்குச் செல்","back":"← AI-gile-க்குத் திரும்பு","lang.button":"மொழி: {name}","lang.dialog":"மொழியைத் தேர்ந்தெடுங்கள்","lang.search":"மொழிகளைத் தேடுங்கள்","lang.none":"பொருந்தும் மொழி இல்லை","lang.notYet":"{name} இன்னும் மொழிபெயர்க்கப்படவில்லை","theme.aria":"ஒளி மற்றும் இருண்ட தீமுக்கு இடையே மாற்று","theme.toLight":"ஒளி தீமுக்கு மாற்று","theme.toDark":"இருண்ட தீமுக்கு மாற்று","index.title":"AI-gile: உங்கள் AI டெவ் டீம், ஒரே போர்டில்","index.description":"AI-gile என்பது AI கோடிங் டீம்களுக்கான கான்பன் போர்டு. நீங்கள் தூங்கும்போது அவர்கள் வேலை செய்கிறார்கள்; நீங்கள் முடிவு செய்ய, சோதிக்க, ஏற்க ஒரு சிறிய குவியல் மட்டும் கிடைக்கும்.","hero.logoAlt":"AI-gile போர்டு ஐகான்","hero.h1.html":"உங்கள் AI டெவ் டீம், ஒரே&nbsp;போர்டில்.","hero.alpha":"🐣 மூடிய ப்ரீ-ஆல்பா","hero.alphaTitle":"ஆரம்ப நிலை, முடியாதது: முயற்சிப்பதற்கு நன்றி!","hero.lede":"நீங்கள் தூங்கும்போது அவர்கள் உருவாக்குகிறார்கள். காலையில் ஒரு சிறிய குவியல்: சில கேள்விகள், சோதிக்க சில விஷயங்கள், ஒன்றிரண்டு ஊதா வைரங்கள். கிளிக் செய்யுங்கள், ஏற்றுக்கொள்ளுங்கள், மீண்டும் காபிக்குத் திரும்புங்கள்.","dl.windows":"Windows ஆப்","dl.browser":"உலாவியில் இயக்குங்கள்","dl.soon":"விரைவில் வருகிறது","dl.notify":"🔔 திறக்கும்போது சொல்லுங்கள்","dl.notifySmall":"ஆல்பா அல்லது பீட்டா","hero.secondary":"அஜைல்தான், ஆனால் டீமுக்கு ஸ்டாண்ட்-அப் காபி தேவையே இல்லை. (இருந்தாலும் ஸ்டாண்ட்-அப் நடத்துவார்கள்.)","pitch.h2":"AI-gile, நீங்கள் விரும்பும் எத்தனை சொற்களிலும்","pitch.lede":"ஒரு சொல்லிலிருந்து 144 வரை நீளத்தைத் தேர்ந்தெடுங்கள். ஒவ்வொரு நீளமும் அந்த அளவுக்காக எழுதப்பட்ட தனி விளக்கம். ஸ்லைடரை இழுக்கவும் அல்லது அம்புக்குறி விசைகளைப் பயன்படுத்தவும்.","pitch.rangeLabel":"சொற்களில் நீளம்","pitch.dice":"🎲 இன்னொரு பதிப்பு","pitch.words.one":"{n} சொல்","pitch.words.other":"{n} சொற்கள்","pitch.letters.one":"{n} எழுத்து","pitch.letters.other":"{n} எழுத்துகள்","pitch.chars.one":"{n} குறி","pitch.chars.other":"{n} குறிகள்","count.line.html.one":"இப்போது போர்டில் {n} கார்டு","count.line.html.other":"இப்போது போர்டில் {n} கார்டுகள்","features.aria":"இது என்ன செய்கிறது","f.pile.h":"உங்களுக்கு ஒரே குவியல்","f.pile.html":"<b>உங்களுக்கு</b> என்பது எல்லா ப்ராஜெக்ட்களிலும் உங்களுக்காகக் காத்திருக்கும் அனைத்தையும் வைத்திருக்கும்: கேள்விகள், சோதிக்க வேண்டியவை, மனிதர் மட்டுமே செய்யக்கூடிய வேலைகள். உங்கள் வரிசை அடுத்தது என்ன, எவ்வளவு நேரம் ஆகும் என்று சொல்லும்.","f.sleep.h":"நீங்கள் தூங்கும்போது வேலை செய்யும் டீம்கள்","f.sleep.p":"ஒவ்வொரு ப்ராஜெக்டுக்கும் ஒரு லீடும் AI ஏஜென்ட்களின் டீமும் உண்டு. கார்டில் கருத்து எழுதினால் டீம் எழுந்து, வேலையை முடித்து, களைத்த மனிதரும் பின்பற்றக்கூடிய படிகளுடன் திருப்பித் தரும்.","f.tester.h":"AI டெஸ்டர் முதலில் சரிபார்க்கிறார்","f.tester.p":"எதுவும் உங்களிடம் வருவதற்கு முன், டெஸ்டர் ஆப்பின் நகலில் படிகளைப் பின்பற்றி, தான் பார்த்ததை ஸ்கிரீன்ஷாட்டுடன் காட்டுவார். தேர்ச்சி பெற்றவற்றை புரட்டிப் பார்த்து ஒரே கிளிக்கில் ஏற்கலாம்.","f.proof.h":"வாக்குறுதி அல்ல, ஆதாரம்","f.proof.p":"ஒவ்வொரு ஒப்படைப்பும் என்ன மாறியது என்று காட்டும்: கோப்புகள், வேறுபாடு, ஸ்கிரீன்ஷாட்கள். முடிந்ததா என்று பார்க்க ஒவ்வொரு ஆப்பையும் திறக்க வேண்டியதில்லை.","f.chat.h":"உங்கள் லீடுகளுடன் அரட்டை","f.chat.p":"Discord போன்ற பக்கப்பட்டை: ஒரு ப்ராஜெக்டுக்கு ஒரு ஐகான், உங்களுக்குத் தேவையானவற்றுக்கு ஊதா வைரங்கள். லீடுக்கு ஒரு யோசனையை அனுப்புங்கள்; அவர் அதை கார்டுகளாகவும் திட்டமாகவும் மாற்றி, ✅ தொடங்கு பொத்தானுடன் தருவார்.","f.tidy.h":"தன்னைத் தானே ஒழுங்குபடுத்திக் கொள்கிறது","f.tidy.p":"தொடர்புடைய கார்டுகள் ஒன்றாக இணையும், குழப்பமான தலைப்புகள் சரிசெய்யப்படும், டோக்கன் சோதனை கோடை எளிமையாக வைக்கும். மாறிமாறிப் பார்க்க குறைவானவை, யோசிக்க குறைவானவை.","f.private.h":"உங்களுடையது, உங்கள் கணினியில்","f.private.li1":"போர்டு உங்கள் சொந்த கணினியில் இயங்கி உங்களுக்கு மட்டுமே பதிலளிக்கும்.","f.private.li2":"மனிதர்களுக்கிடையேயான தனிப்பட்ட செய்திகள் தொடக்கம் முதல் இறுதி வரை குறியாக்கம் செய்யப்படுகின்றன.","f.private.li3":"கணக்குகள் இல்லை, டிராக்கர்கள் இல்லை, குக்கீகள் இல்லை.","f.lang.h":"உங்கள் மொழியில்","f.lang.p":"டச்சு, வெல்ஷ், ஜப்பானியம் முதல் கடற்கொள்ளையர், யோடா, க்ளிங்கன் வரை 120-க்கும் மேற்பட்ட மொழிகள், டெவலப்பர் சொற்களுக்காக ஆங்கிலத்துக்கு விரைவாகத் திரும்பும் வசதியுடன்.","tl.aria":"முதல் உரையாடல் முதல் திட்டம் வரையிலான காலவரிசை","tl.h2":"முதல் அரட்டை முதல் அடுத்து வருவது வரை","tl.lede":"உண்மையான தேதிகளும் நேரங்களும், உங்கள் சொந்த நேர மண்டலத்தில். இன்றுக்குப் பிறகு அது திட்டம் மட்டுமே, தேதிகள் எதுவும் உறுதியளிக்கப்படவில்லை.","tl.today":"இன்று","tl.planned":"திட்டமிடப்பட்டது","tl.cards.one":"{n} கார்டு","tl.cards.other":"{n} கார்டுகள்","join.h2":"இணையுங்கள்","join.lede":"AI-gile-ஐ ஒரு சிறிய மனிதரும் பொறுமையான ஏராளமான ஏஜென்ட்களும் உருவாக்குகிறார்கள். இப்போதைக்கு இது தனிப்பட்டது, நண்பர்களுடன் மூடிய ஆல்பாவில் உள்ளது. திறக்கும்போது முயற்சிக்க விரும்புகிறீர்களா?","join.btn":"ஆர்வத்தைப் பதிவு செய்","join.small":"மின்னஞ்சல் அனுப்புவோம், வேறு எதுவும் இல்லை","footer.tag":"AI-gile. டிராக்கர்கள் இல்லை, குக்கீகள் இல்லை, ஸ்டாண்ட்-அப் காபி இல்லை.","footer.licence":"வணிக உரிமம்","footer.status":"நிலை","form.sending":"அனுப்புகிறது…","form.failed":"அது நடக்கவில்லை: பிறகு மீண்டும் முயற்சிக்கவும்.","form.offline":"AI-gile-ஐ அடைய முடியவில்லை: பிறகு மீண்டும் முயற்சிக்கவும்.","interest.title":"AI-gile: ஆல்பா திறக்கும்போது சொல்லுங்கள்","interest.description":"AI-gile-இன் மூடிய ஆல்பா அல்லது பீட்டா திறக்கும்போது தெரிந்துகொள்ள உங்கள் மின்னஞ்சலை விடுங்கள்.","interest.h1":"🔔 திறக்கும்போது சொல்லுங்கள்","interest.lede":"AI-gile மூடிய ப்ரீ-ஆல்பாவில் உள்ளது. உங்கள் மின்னஞ்சலை விடுங்கள்; உங்களுக்கு இடம் இருக்கும்போது ஒரே ஒரு முறை எழுதுவோம்.","interest.email":"உங்கள் மின்னஞ்சல்","interest.which":"எந்தச் சோதனை?","interest.alpha":"மூடிய ஆல்பா: ஆரம்பம், கரடுமுரடு, நிறைய மாற்றங்கள்","interest.beta":"பீட்டா: நிலையானது, பிறகு","interest.both":"எதுவானாலும், எது முதலில் வருகிறதோ","interest.submit":"பட்டியலில் சேருங்கள்","interest.thanks":"நன்றி! நீங்கள் பட்டியலில் இருக்கிறீர்கள்.","interest.kept":"உங்கள் மின்னஞ்சலும் நீங்கள் தேர்ந்த சோதனையும் மட்டுமே, இந்தப் பட்டியலுக்கு மட்டும் சேமிக்கப்படும். செய்திமடல் இல்லை, டிராக்கர்கள் இல்லை.","licence.title":"AI-gile: வணிக உரிமம்","licence.description":"உங்கள் வணிகத்தில் AI-gile பயன்படுத்துகிறீர்களா? இலவச வணிக உரிமத்துக்கு விண்ணப்பியுங்கள்.","licence.h1":"📜 வணிக உரிமம்","licence.lede":"வேலையில் AI-gile பயன்படுத்துகிறீர்களா? நீங்கள் யார், என்ன செய்கிறீர்கள் என்று சொல்லுங்கள். அது ஏதாவது நன்மை செய்தால், உரிமம் இலவசம்.","licence.company":"நிறுவனம்","licence.website":"இணையதளம்","licence.what":"நீங்கள் என்ன செய்கிறீர்கள்","licence.how":"இது உலகுக்கு எப்படி உதவுகிறது","licence.email":"மின்னஞ்சல்","licence.submit":"விண்ணப்பி","licence.thanks":"நன்றி! மின்னஞ்சலில் பதிலளிப்போம்.","status.title":"AI-gile நிலை","status.h1":"AI-gile நிலை","status.quiet":"அமைதியாக இருக்கிறது","status.checking":"சரிபார்க்கிறது…","status.offline":"நிலைச் சேவையை இப்போது அடைய முடியவில்லை (மீண்டும் முயல்கிறது)","status.updated":"{ago} புதுப்பிக்கப்பட்டது","status.justNow":"இப்போதுதான்","status.min":"{n} நிமிடம் முன்","status.hours":"{n} மணி முன்","status.days":"{n} நாள் முன்","live.h2":"இது உருவாவதை நேரலையில் பாருங்கள்","live.caption":"ஒவ்வொரு அட்டையும் மறைக்கப்பட்டுள்ளது: நீங்கள் வேலையின் வடிவத்தைப் பார்க்கிறீர்கள், சொற்களை அல்ல.","live.watching.one":"நேரலை: {n} பேர் பார்க்கிறார்கள்","live.watching.other":"நேரலை: {n} பேர் பார்க்கிறார்கள்","live.offline":"நேரலைப் பலகை சற்று ஓய்வெடுக்கிறது. விரைவில் மீண்டும் பாருங்கள்.","live.cols":"பேக்லாக்|செய்ய வேண்டியவை|நடப்பில்|டீம் சரிபார்க்கிறது|நீங்கள் டெஸ்ட் செய்ய|டீமுக்கு|முடிந்தது","live.last.now":"கடைசி அட்டை இப்போதுதான் நகர்த்தப்பட்டது","live.last.min.one":"கடைசி அட்டை {n} நிமிடம் முன்பு நகர்த்தப்பட்டது","live.last.min.other":"கடைசி அட்டை {n} நிமிடங்கள் முன்பு நகர்த்தப்பட்டது","live.last.hour.one":"கடைசி அட்டை {n} மணி நேரம் முன்பு நகர்த்தப்பட்டது","live.last.hour.other":"கடைசி அட்டை {n} மணி நேரம் முன்பு நகர்த்தப்பட்டது","live.last.day.one":"கடைசி அட்டை {n} நாள் முன்பு நகர்த்தப்பட்டது","live.last.day.other":"கடைசி அட்டை {n} நாட்கள் முன்பு நகர்த்தப்பட்டது"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["கான்பன்.","ரோபோக்கள்.","ஒப்படைத்தல்."]},{"n":2,"texts":["ரோபோ கான்பன்.","ஏஜென்ட்கள், ஒழுங்காக.","யோசனைகள், உருவாகின்றன."]},{"n":3,"texts":["ரோபோக்களுக்கான கான்பன்.","யோசனை அம்சமாகிறது.","இலவச ஏஜென்ட் கான்பன்."]},{"n":5,"texts":["ஏஜென்ட்கள் நடத்தும் கான்பன் போர்டு.","நீங்கள் எழுதுங்கள். ஏஜென்ட்கள் உருவாக்குவார்கள்.","இலவசம், உள்ளூர், சோதிக்கப்பட்டது, கொஞ்சம் குறும்பு."]},{"n":8,"texts":["AI ஏஜென்ட்கள் வேலை செய்யும் இலவச கான்பன் போர்டு.","யோசனையை எழுதுங்கள். ஏஜென்ட்கள் உருவாக்கும். நீங்கள் ஏற்கலாம்.","ஒரு மனிதருக்கும் பல பொறுமையான ரோபோக்களுக்குமான அஜைல்."]},{"n":13,"texts":["AI ஏஜென்ட்கள் கார்டுகளை எடுத்து உருவாக்கும், உங்கள் கணினியில் இயங்கும் ஒரு கான்பன் போர்டு.","உங்கள் யோசனையை எழுதுங்கள். அதை ஏஜென்ட்களின் ஒரு டீம் உருவாக்கும். ஒரு டெஸ்டர் அதைச் சரிபார்த்த பிறகு, நீங்களே முடிவு செய்வீர்கள்.","இலவசம், கணக்கு இல்லை, டிராக்கர் இல்லை: ஒரு போர்டு, சில ரோபோக்கள், நீங்களே தலைவர்."]},{"n":21,"texts":["AI-gile என்பது AI கோடிங் ஏஜென்ட்களுடன் சேர்ந்து வேலை செய்ய உதவும் ஒரு கான்பன் போர்டு. கார்டுகளை அவை எடுத்துச் செய்யும்; அவற்றைச் சோதித்து ஏற்பது நீங்கள்.","ஒவ்வொரு ப்ராஜெக்டுக்கும் ஒரு லீடும், AI ஏஜென்ட்கள் அடங்கிய ஒரு டீமும் கிடைக்கும். எந்த ஒரு கார்டிலும் கருத்து எழுதினால், உடனே டீம் வேலையைத் தொடங்கும்.","உங்கள் சொந்த கணினியில் ஓடும், இலவசமான ஒரு தனிப்பட்ட செய்ய வேண்டியவை பட்டியல் இது. வேலை செய்பவர்கள் எல்லாம் ரோபோக்கள். சரி என்று சொல்பவர் மட்டும் நீங்கள்."]},{"n":34,"texts":["உங்கள் யோசனைகளை ஒரு போர்டில் வைக்கிறீர்கள். AI ஏஜென்ட்களின் ஒரு டீம் அவற்றை வேலை செய்யும் அம்சங்களாக மாற்றி, சோதித்து, நீங்கள் முயன்று பார்க்கத் தேவையான படிகளுடன் திருப்பித் தருகிறது. நீங்கள் சொல்லும் வரை எதுவும் முடிந்ததாகக் கணக்கில் வராது.","AI-gile என்பது வீட்டிலேயே செய்த ஒரு கான்பன் போர்டு. இதை ரிச், தான் இப்போது நிர்வகிக்கும் அதே ஏஜென்ட்களின் பெரிய உதவியுடன் உருவாக்கினார். இது இலவசம், உங்கள் கணினியில் ஓடும், நண்பர்களுடன் பகிரப்படுகிறது, விற்கப்படுவதில்லை. இது நண்பர்களுக்காகச் செய்த ஒரு சிறிய முயற்சி.","பேக்லாக் முதல் முடிந்தது வரை நெடுவரிசைகள் கொண்ட சாதாரண கான்பன் போர்டை நினைத்துப் பாருங்கள், கார்டுகளை AI ஏஜென்ட்கள் எடுக்கின்றன என்பது மட்டும் வேறுபாடு. அவை முன்னேற்றம் சொல்லும், சிக்கினால் கேட்கும், உங்கள் பெருவிரல் உயர்வுக்காக எப்போதும் காத்திருக்கும்."]},{"n":55,"texts":["AI-gile என்பது ஒரு கான்பன் போர்டு, இதில் டீமே AI ஏஜென்ட்களால் ஆனது. ஒவ்வொரு ப்ராஜெக்டிலும் வேலையைத் திட்டமிடும் ஒரு லீடும், அதை உருவாக்கும் உதவியாளர்களும் இருக்கிறார்கள். ஒரு அம்சம் தயாரானதும் AI டெஸ்டர் அதைச் சோதித்து ஒரு ஸ்கிரீன்ஷாட் எடுப்பார், பிறகு அது உங்கள் குவியலுக்கு வந்து சேரும். அதை ஏற்கலாம், அல்லது கருத்து எழுதினால் அவர்கள் மீண்டும் செய்வார்கள்.","இது ஒருவர் பல AI கோடிங் அமர்வுகளை ஒரே நேரத்தில் கண்காணிக்க ஆரம்பித்த ஒரு வழி, பிறகு வளர்ந்து ஒரு முழுமையான போர்டு ஆனது. இது உங்கள் கணினியிலேயே ஓடும், கணக்கு எதுவும் தேவையில்லை, டிராக்கர்களும் இல்லை. நண்பர்களுக்கும் ஆர்வமுள்ள எவருக்கும் இலவசம். இது இன்னும் முடியவில்லை, அதனால் சில கரடுமுரடான இடங்களையும் எப்போதாவது ஒரு ஆச்சரியத்தையும் எதிர்பாருங்கள். அதைப் புரிந்துகொண்டு பொறுத்துக்கொள்ளுங்கள், நன்றி.","நேர்மையான பதிப்பு இதோ. யோசனைகள் வைத்திருப்பதும் முடிவுகளைச் சரிபார்ப்பதும் இன்னும் உங்கள் வேலைதான். அதற்கு நடுவில் உள்ள எல்லாவற்றையும் AI-gile செய்கிறது: கார்டுகளை ஒழுங்காக வைக்கிறது, நீங்கள் கருத்து எழுதினால் சரியான ஏஜென்ட்டை எழுப்புகிறது, என்ன மாறியது என்று சரியாகக் காட்டுகிறது, இவை எல்லாவற்றையும் உங்களுக்காக ஒரே ஒரு சிறிய குவியலில் வைக்கிறது. அதனால் ஒரு ஆப்பிலிருந்து இன்னொன்றுக்கு அலைய வேண்டியதில்லை, எதையும் தவற விடவும் மாட்டீர்கள்."]},{"n":89,"texts":["AI-gile என்பது நீங்கள் உங்கள் சொந்த கணினியில் ஓட்டும் ஒரு இலவச கான்பன் போர்டு. மனிதர்களுக்குப் பதிலாக, ஒவ்வொரு ப்ராஜெக்டிலும் AI ஏஜென்ட்களின் ஒரு டீம் இருக்கிறது: உங்கள் யோசனைகளை கார்டுகளாகவும் ஒரு திட்டமாகவும் மாற்றும் ஒரு லீடு, முன்னுரிமை வரிசையில் கார்டுகளை எடுத்துச் செய்யும் உதவியாளர்கள். ஏதாவது உருவானதும், ஒரு AI டெஸ்டர் சோதனைப் படிகளைப் பின்பற்றி, தான் பார்த்ததை உங்களுக்குக் காட்டுவார். பிறகு அது \"உங்களுக்கு\" என்ற ஒரே குவியலில் காத்திருக்கும். நீங்கள் ஏற்கலாம், அல்லது கருத்து எழுதினால் டீம் மீண்டும் ஒரு முறை முயலும். நீங்கள் இல்லாமல் எதுவும் ஒருபோதும் முடிந்தது நெடுவரிசையை அடையாது. இதுவே இதன் முக்கிய விதி.","நீங்கள் எதிர்பார்க்காத சில விஷயங்கள் உண்டு. நீங்கள் தூங்கும்போது இரவுக் காவல், உங்கள் பதில் தேவைப்படாத கார்டுகளைத் தேர்ந்தெடுத்து, செய்ய வேண்டியவை நெடுவரிசையை நிரப்பி வைக்கும். ஏஜென்ட்கள் இன்றும் இந்த வாரமும் எவ்வளவு பயன்படுத்தின என்பதை ஒரு டோக்கன் எண்ணி காட்டும், No Token Mode அவற்றைச் செலவழிப்பதை நிறுத்தச் சொல்லும். நண்பர்களுக்குச் செய்தி அனுப்பலாம், தனிப்பட்ட செய்திகள் தொடக்கம் முதல் இறுதி வரை குறியாக்கம் செய்யப்படுகின்றன. போர்டு டச்சு, ஃபிளெமிஷ், கடற்கொள்ளையர், க்ளிங்கன் உட்பட சுமார் 120 மொழிகளில் பேசும். இவை எதற்கும் ஒரு பைசா கூடச் செலவில்லை, உங்களிடம் எதையும் விற்க யாரும் முயலவும் இல்லை. இவை எல்லாம் நண்பர்களுக்காக, அன்புடன் செய்யப்பட்டவை.","AI-gile ஒரு சிறிய, தனிப்பட்ட திட்டம், ஒரு நிறுவனம் அல்ல. பல AI கோடிங் ப்ராஜெக்ட்களை, ஒவ்வொரு ஆப்பையும் திறந்து பார்க்காமலே கவனிக்க ரிச் விரும்பினார். அதனால் அவரும் ஏஜென்ட்களும் அதற்காக ஒரு போர்டை உருவாக்கி, பிறகு அந்தப் போர்டையே பயன்படுத்தி அதன் மீதிப் பகுதியையும் உருவாக்கினார்கள். இது மூடிய ப்ரீ-ஆல்பாவில் இருக்கிறது, அதாவது ஒரு சில நண்பர்களுக்கு, பெரும்பாலும் வேலை செய்கிறது. விலைப் பக்கம் இல்லை, செய்திமடல் இல்லை, வளர்ச்சித் திட்டமும் இல்லை. பயனுள்ளதாகத் தோன்றினால், இது இன்னும் கொஞ்சம் திறந்ததும் முயன்று பார்க்கக் கேட்கலாம். அதுவரை பொறுமையாகக் காத்திருந்து, எங்களுடன் சேர்ந்து இதைச் சோதிக்க வாருங்கள், உங்கள் கருத்துகள் எங்களுக்கு மிகவும் உதவும்."]},{"n":144,"texts":["AI-gile என்பது ஒரு மனிதருக்கும் பல AI ஏஜென்ட்களுக்குமான ஒரு கான்பன் போர்டு. இது உங்கள் சொந்த கணினியில் ஓடும், முற்றிலும் இலவசம். நீங்கள் ப்ராஜெக்ட்களைச் சேர்க்கிறீர்கள், ஒவ்வொரு ப்ராஜெக்டுக்கும் ஒரு லீடும் ஒரு சிறிய டீமும் கிடைக்கும். Discord போல லீடுடன் அரட்டையடித்து ஒரு யோசனையை விவரிக்கிறீர்கள்; லீடு அதை கார்டுகளாகவும் ஒரு திட்டமாகவும் மாற்றி, நீங்கள் \"தொடங்கு\" என்று அழுத்தும் வரை காத்திருக்கும். மொழி மாதிரிகளுக்காகவே செய்யப்பட்ட ஒரு எளிய கட்டளை வரிக் கருவியைப் பயன்படுத்தி, டீம் கார்டுகளை முன்னுரிமை வரிசையில் ஒன்றன் பின் ஒன்றாகச் செய்யும். எதுவும் உங்களிடம் திரும்பி வருவதற்கு முன், ஒரு AI டெஸ்டர் ஆப்பின் ஒரு நகலில் படிகளைப் பின்பற்றி, ஒரு ஸ்கிரீன்ஷாட்டையும் இணைக்கும். முடிந்த வேலை, மாறிய கோப்புகளுடனும் வேறுபாட்டுடனும் உங்கள் குவியலில் வந்து சேரும். நீங்கள் அதை ஏற்கலாம், அல்லது ஒரு கருத்து எழுதினால் டீம் எழுந்து மீண்டும் முயலும். ஒரு கார்டை \"முடிந்தது\" நெடுவரிசைக்கு நகர்த்த உங்களால் மட்டுமே முடியும். அதனால் எந்த நேரத்திலும், எந்தக் கார்டு எங்கே இருக்கிறது என்பதை நீங்கள் ஒரே பார்வையில் தெரிந்துகொள்ளலாம், எதையும் தேட வேண்டியதில்லை.","AI-gile-உடன் ஒரு நாள், தோராயமாக இப்படி இருக்கும். மாலையில் நீங்கள் சில கருத்துகளை எழுதி வைக்கிறீர்கள்: இந்தப் பொத்தான் தவறான இடத்தில் இருக்கிறது, அந்தப் பட்டியலை வரிசைப்படுத்த வேண்டும், இருண்ட பயன்முறை கிடைக்குமா. பிறகு தூங்கப் போகிறீர்கள். ஏஜென்ட்கள் அந்தக் கருத்துகளைப் படித்து, மாற்றங்களைச் செய்து, அவற்றைச் சோதித்து, உங்களிடம் திருப்பித் தருகின்றன. செய்ய வேண்டியவை காலியாகிவிட்டால், இரவுக் காவல் உங்கள் பதில் தேவைப்படாத கார்டுகளைக் கொண்டு பேக்லாக்கிலிருந்து அதை நிரப்பும். காலையில் ஒரே ஒரு சிறிய குவியல் காத்திருக்கும்: ஓரிரு கேள்விகள், சோதிக்க சில விஷயங்கள், ஒவ்வொன்றும் தூக்கக் கலக்கத்தில் இருப்பவரும் பின்பற்றக்கூடிய படிகளுடனும், அது வேலை செய்வதைக் காட்டும் ஒரு ஸ்கிரீன்ஷாட்டுடனும். நீங்கள் கிளிக் செய்து, நல்லவற்றை ஏற்று, மீதியைத் திருப்பி அனுப்புகிறீர்கள். இவை எல்லாம் எவ்வளவு பயன்படுத்தின என்பதை டோக்கன் எண்ணி காட்டும், சிக்கனமான வாரங்களுக்கு No Token Mode இருக்கிறது. பிறகு நீங்கள் காலை உணவு சாப்பிடுகிறீர்கள், அதில் மட்டும் ஏஜென்ட்களால் இன்னும் உதவ முடியாது. அடுத்த நாள் இரவும் இதே போல் தொடரும், அப்போது உங்களுக்கு வேண்டியது ஒரு கப் தேநீர் மட்டும்தான்.","முதலில், AI-gile என்னவாக இல்லை என்று பார்ப்போம். இது ஒரு ஸ்டார்ட்-அப் அல்ல, விற்பனைக்கு இல்லை, உங்கள் தரவை யாரும் சேகரிக்கவும் இல்லை. இது உங்கள் கணினியில் ஓடும் இலவசப் போர்டு, கணக்குகள் இல்லை, டிராக்கர்கள் இல்லை, குக்கீகளும் இல்லை. இது என்னவாக இருக்கிறது என்றால்: உங்கள் எல்லா AI கோடிங் ப்ராஜெக்ட்களையும் ஒரே நேரத்தில் பார்க்க ஒரு ஒழுங்கான இடம், கார்டுகளை ஏஜென்ட்களின் டீம் செய்ய, முடிவுகளை நீங்கள் எடுக்க. தொடர்புடைய கார்டுகளை ஒன்றாக இணைக்கிறது, குழப்பமான தலைப்புகளைச் சரிசெய்கிறது, கோடு எவ்வளவு எளிமையாக இருக்கிறது என்றும் கவனிக்கிறது. டச்சு, ஃபிளெமிஷ் முதல் கடற்கொள்ளையர், க்ளிங்கன் வரை சுமார் 120 மொழிகளில் பேசுகிறது. நண்பர்கள் ஒருவருக்கொருவர் தனிப்பட்ட முறையில், குறியாக்கத்துடன் செய்தி அனுப்பிக்கொள்ளலாம். இதை ரிச்சும் பொறுமையான ஏராளமான ஏஜென்ட்களும் சேர்ந்து உருவாக்கினார்கள், பெரும்பாலும் இதையே பயன்படுத்தி. இது மூடிய ப்ரீ-ஆல்பாவில் இருக்கிறது, அதனால் சில இடங்களில் கரடுமுரடாக இருக்கும். வேடிக்கையாகத் தோன்றினால், அன்பாகக் கேளுங்கள், சீக்கிரமே உள்ளே வரலாம். எனவே உங்களுக்கு விருப்பமிருந்தால், எந்தத் தயக்கமும் இல்லாமல் எங்களிடம் வந்து கேளுங்கள், நாங்கள் மகிழ்வோம்."]}],"quips":{"1":"ஒரே சொல். துணிச்சல். ஒருவேளை அதிகத் துணிச்சல்.","3":"மூன்று சொற்கள். பெரும்பாலான தயாரிப்புப் பக்கங்களை விட ஏற்கனவே நேர்மையானது.","8":"எட்டுச் சொற்கள். இன்னும் ஸ்டாண்ட்-அப்பை விடச் சிறியது.","21":"நீளங்கள் ஸ்டோரி பாயிண்ட்கள், சொல்லப்போனால். நிச்சயமாக அப்படித்தான்.","55":"ஐம்பத்தைந்து சொற்கள். இதைப் படிக்கும்போது இரண்டு கார்டுகள் முடிந்துவிட்டன.","144":"இதுதான் நீளமானது. 233 என்பது இல்லை. ஏஜென்ட்கள் தூங்கப் போய்விட்டன."}},"timeline":{"first-idea.name":"முதல் யோசனை","first-idea.line":"ஒரு வரி கோடும் இல்லாத காலத்தில் நடந்த முதல் உரையாடல்.","first-board.name":"முதல் போர்டு","first-board.line":"தன் சொந்த உருவாக்கத்தைத் தானே கண்காணிக்கும் போர்டு: கார்டுகள், நெடுவரிசைகள், இழுத்துவிடுதல், ப்ராஜெக்ட்கள்.","team-roles.name":"டீமும் பங்குகளும்","team-roles.line":"ஏஜென்ட் சுயவிவரங்கள், டீம் வார்ப்புருக்கள், இடங்கள், யார் என்ன செய்கிறார்கள்.","install.name":"நிறுவலும் வெளியீடுகளும்","install.line":"நண்பர் நிறுவக்கூடிய ஒரு zip, தானியங்கிப் புதுப்பிப்பு, சேனல்கள், பின்னோக்கித் திரும்புதல்.","usage-saver.name":"பயன்பாட்டுச் சேமிப்பு","usage-saver.line":"இயக்கங்களுக்கான செலவை அளவிடுங்கள், கோடை எளிமையாக வையுங்கள், உங்கள் வரம்பைச் சேமியுங்கள்.","friends.name":"நண்பர்களும் பகிர்வும்","friends.line":"தனிப்பட்ட செய்திகள், குறியாக்கப்பட்ட ரிலே, அழைப்புகள், பங்குகள், பகிரப்பட்ட ப்ராஜெக்ட்கள்.","languages.name":"மொழிகள்","languages.line":"ஒவ்வொரு திரை உரையும் ஒரு மொழிக் கோப்பில், முதலில் டச்சு மற்றும் ஃபிளெமிஷ்.","ai-tester.name":"AI டெஸ்டர்","ai-tester.line":"ஒவ்வொரு ஒப்படைப்பையும் டெஸ்டர் முதலில் சரிபார்த்து, தான் பார்த்ததைக் காட்டுகிறார்.","website.name":"இணையதளம்","website.line":"aigile.lol, முன்னோட்டப் பக்கம் மற்றும் இந்தக் காலவரிசை.","streaming.name":"அரட்டையும் ஸ்ட்ரீமிங்கும்","streaming.line":"Discord, Twitch, OBS, ஸ்ட்ரீமர் பயன்முறை, GIF-களும் எமோஜிகளும்.","no-ai.name":"AI இல்லாத பதிப்பு","no-ai.line":"AI இல்லாமல் கோடிங் செய்பவர்களுக்கான போர்டு, மற்றும் பொது போர்டுகள்.","night-watch.name":"இரவுக் காவல்","night-watch.line":"நீங்கள் தூங்கும்போது காவலரும் Scrum Master-உம் டீம்களை வேலையில் வைத்திருக்கிறார்கள்.","p-more.name":"மற்ற எல்லாம்","p-more.line":"தங்கள் முறைக்காகக் காத்திருக்கும் சிறிய யோசனைகள்.","p-android.name":"போனும் Android-உம்","p-android.line":"போனிலிருந்து உங்கள் போர்டை அணுகுங்கள், பிறகு சொந்த Android ஆப்.","p-release.name":"ஆல்பாவும் அதற்குப் பிறகும்","p-release.line":"மூடிய ஆல்பா, நேரடித் தளம், பிறகு பீட்டா.","p-languages.name":"மேலும் மொழிகள்","p-languages.line":"நூற்றுக்கும் மேற்பட்ட மொழிகள், கற்பவர்களுக்கான மூழ்கிக் கற்கும் பயன்முறை.","p-engines.name":"மேலும் AI என்ஜின்கள்","p-engines.line":"ஒவ்வொரு ஏஜென்ட்டுக்கும் Claude, Codex அல்லது Gemini தேர்ந்தெடுங்கள்.","p-pro.name":"தொழில்முறை நடைமுறை","p-pro.line":"ஆபத்து லேபிள்கள், மெர்ஜ் வாயில்கள், சம்பவ கார்டுகள், பாதுகாப்புத் தடுப்புகள்.","p-self.name":"உங்களைக் கவனித்துக்கொள்ள","p-self.line":"சோர்வுப் பயன்முறை, சுய-கவனிப்பு நினைவூட்டல்கள், 4:20.","p-servers.name":"சர்வர்களும் வளர்ச்சியும்","p-servers.line":"உலகளாவிய சர்வர் அமைப்புகள், பங்குகள், வளர்ச்சிக்கான திட்டமிடல்.","p-livestream.name":"ஸ்ட்ரீமிங் கூடுதல்கள்","p-livestream.line":"Twitch அரட்டை, தனிப்பயன் எமோஜிகள், பொது நேரலைக் காட்சி."},"words":{"button":"📖 டெவ் சொற்கள்","h":"📖 டெவ் சொற்களின் விளக்கம்","intro":"டெவலப்பர்கள் (மற்றும் AI டீம்கள்) பயன்படுத்தும் சொற்கள், எளிய தமிழில்.","search":"ஒரு சொல்லைத் தேடு…","none":"அந்தச் சொல் எதுவும் பொருந்தவில்லை.","close":"மூடு","list":[{"id":"backlog","word":"பேக்லாக்","text":"இன்னும் திட்டமிடாத ஐடியாக்களும் வேலையும். செய்ய வேண்டியவைக்கு நகரும் வரை அங்கே எதுவும் செய்யப்படாது."},{"id":"sprint","word":"ஸ்பிரிண்ட்","text":"முடிக்க வேண்டிய ஒப்புக்கொண்ட கார்டுகளுடன் கூடிய ஒரு குறுகிய வேலைக் காலம் (பெரும்பாலும் ஒன்று அல்லது இரண்டு வாரம்).","also":["ஸ்பிரிண்ட்கள்","sprint","sprints"]},{"id":"standup","word":"ஸ்டாண்ட்-அப்","text":"ஒரு விரைவான சந்திப்பு: ஒவ்வொரு டீம் உறுப்பினரும் என்ன செய்தார், அடுத்து என்ன செய்வார், எது அவரைத் தடுக்கிறது.","also":["ஸ்டாண்டப்","ஸ்டாண்ட்-அப்கள்","standup","stand-up","stand-ups"]},{"id":"bug","word":"பக்","text":"இருக்க வேண்டியபடி வேலை செய்யாத ஒன்று.","also":["பக்குகள்","bug","bugs"]},{"id":"test","word":"டெஸ்ட்","text":"முடிந்த வேலையை ஏற்றுக்கொள்வதற்கு முன், கேட்டபடி செய்கிறதா என்று முயன்று பார்ப்பது.","also":["டெஸ்ட்கள்","test","tests"],"noTip":1},{"id":"commit","word":"கமிட்","text":"கோடின் சேமிக்கப்பட்ட ஒரு ஸ்னாப்ஷாட், என்ன மாறியது என்ற சிறு குறிப்புடன். எப்போது வேண்டுமானாலும் ஒன்றுக்குத் திரும்பிப் போகலாம்.","also":["கமிட்கள்","commit","commits"]},{"id":"push","word":"புஷ்","text":"சேமித்த ஸ்னாப்ஷாட்களை (கமிட்களை) இந்தக் கணினியிலிருந்து GitHub-க்கு அனுப்புவது, அதனால் அவை காப்புப் பிரதியாகவும் பகிரப்பட்டதாகவும் இருக்கும்."},{"id":"branch","word":"பிராஞ்ச்","text":"கோடில் தனி வேலைக் கிளை, அதனால் முதன்மைப் பதிப்பைத் தொடாமல் மாற்றங்கள் செய்யலாம்.","also":["பிராஞ்சுகள்","branch","branches"]},{"id":"merge","word":"மெர்ஜ்","text":"ஒரு பிராஞ்சின் மாற்றங்களை மீண்டும் முதன்மைப் பதிப்புடன் சேர்ப்பது."},{"id":"repo","word":"ரெப்போ","text":"ப்ராஜெக்டின் கோட் கோப்புறையும் அதன் முழு கமிட் வரலாறும், பொதுவாக GitHub-இலும் வைக்கப்படும்.","also":["ரெபாசிட்டரி","repo","repository"]},{"id":"refactor","word":"ரீஃபாக்டர்","text":"கோடு செய்வதை மாற்றாமல் அதைச் சீர்செய்வது: சிறிய கோப்புகள், தெளிவான பெயர்கள், குறைவான திரும்பத் திரும்ப எழுதிய கோடு."},{"id":"deploy","word":"டெப்ளாய்","text":"புதிய பதிப்பை நேரலைக்குக் கொண்டுவருவது, எடுத்துக்காட்டாக மக்கள் பயன்படுத்தும் சர்வரில்."},{"id":"kanban","word":"கான்பன்","text":"நெடுவரிசைகள் (செய்ய வேண்டியவை, நடப்பில், முடிந்தது) கொண்ட போர்டு, வேலை நடக்கும்போது கார்டுகள் இடமிருந்து வலமாக நகரும்."},{"id":"wip","word":"WIP வரம்பு","text":"நடப்பில் உள்ள வேலை: ஒரு நெடுவரிசை அதிகபட்சம் வைத்திருக்க வேண்டிய கார்டுகள், அதனால் டீம் மேலும் தொடங்கும் முன் முடிக்கும்.","also":["WIP"]},{"id":"pr","word":"புல் ரிக்வெஸ்ட்","text":"ஒரு பிராஞ்சின் மாற்றங்களைச் சரிபார்த்து முதன்மைப் பதிப்பில் மெர்ஜ் செய்யும்படி கேட்பது.","also":["PR"]},{"id":"hook","word":"ஹூக்","text":"ஒரு குறிப்பிட்ட தருணத்தில் தானே இயங்கும் சிறு கட்டளை, எ.கா. ஒரு AI செஷன் தொடங்கும்போது, அதனால் டீம் உங்கள் கருத்துகளைக் கேட்கிறது.","also":["ஹூக்குகள்","hook","hooks"]},{"id":"token","word":"டோக்கன்","text":"AI பயன்பாடு கணக்கிடப்படும் அலகு: படித்த அல்லது எழுதிய உரையின் சில எழுத்துகள். குறைவான டோக்கன்கள் என்றால் உங்கள் திட்டத்தில் அதிகம் மீதம்.","also":["டோக்கன்கள்","token","tokens"]},{"id":"agent","word":"ஏஜென்ட்","text":"ஒரு பணியில் தானே வேலை செய்யும் AI: கோடைப் படிக்கும், மாற்றங்கள் செய்யும், சோதனைகளை இயக்கும், திரும்பத் தெரிவிக்கும்.","also":["ஏஜென்ட்கள்","agent","agents"]}]}};
